import React from 'react';
import styled from 'styled-components';

const WorkExperienceContainer = styled.div`
  padding: 20px;
  max-width: 800px;
  margin: 0 auto;
`;

const ExperienceSection = styled.div`
  margin-bottom: 30px;
`;

const JobTitle = styled.h2`
  font-size: 24px;
  margin-bottom: 10px;
`;

const CompanyName = styled.h3`
  font-size: 20px;
  margin-bottom: 5px;
`;

const Duration = styled.p`
  font-size: 16px;
  color: #666;
  margin-bottom: 10px;
`;

const Responsibilities = styled.ul`
  list-style-type: disc;
  margin-left: 20px;
`;

const ResponsibilityItem = styled.li`
  font-size: 16px;
  margin-bottom: 5px;
`;

const WorkExperience = () => {
  return (
    <WorkExperienceContainer>
      <h1>WORK EXPERIENCE</h1>

      <ExperienceSection>
        <JobTitle>Head Chef</JobTitle>
        <CompanyName>Express body by butter, Lahore</CompanyName>
        <Duration>2022 - 2024</Duration>
        <Responsibilities>
          <ResponsibilityItem>Oversee daily bakery operations, ensuring high standards of quality and efficiency.</ResponsibilityItem>
          <ResponsibilityItem>Develop and create new recipes, including specialty breads, pastries, and desserts.</ResponsibilityItem>
          <ResponsibilityItem>Manage and train kitchen staff, guiding baking techniques and food safety.</ResponsibilityItem>
          <ResponsibilityItem>Maintain inventory, order ingredients, and manage stock levels to minimize waste.</ResponsibilityItem>
          <ResponsibilityItem>Ensure compliance with health and safety regulations including food handling and cleanliness standards.</ResponsibilityItem>
        </Responsibilities>
      </ExperienceSection>

      <ExperienceSection>
        <JobTitle>Assistant Chef</JobTitle>
        <CompanyName>Sweettooth, Lahore</CompanyName>
        <Duration>2021 - 2022</Duration>
        <Responsibilities>
          <ResponsibilityItem>Responsible for baking a variety of products, including brownies, waffles, and other desserts.</ResponsibilityItem>
          <ResponsibilityItem>Prepared ice creams and refreshing beverages such as lemonades and mint margaritas.</ResponsibilityItem>
        </Responsibilities>
      </ExperienceSection>

      <ExperienceSection>
        <JobTitle>Assistant Chef</JobTitle>
        <CompanyName>National Bakery, Gilgit</CompanyName>
        <Duration>2019 - 2021</Duration>
        <Responsibilities>
          <ResponsibilityItem>Managed kitchen operations in the absence of the head chef, resulting in minimal disruption to service.</ResponsibilityItem>
          <ResponsibilityItem>Collaborated with the head chef to develop and execute weekly menu plans.</ResponsibilityItem>
        </Responsibilities>
      </ExperienceSection>

      <ExperienceSection>
        <JobTitle>Assistant Chef</JobTitle>
        <CompanyName>Tibet Motel Sost, Hunza</CompanyName>
        <Duration>2017 - 2018</Duration>
        <Responsibilities>
          <ResponsibilityItem>Assisted in daily kitchen operations and food preparation.</ResponsibilityItem>
        </Responsibilities>
      </ExperienceSection>
    </WorkExperienceContainer>
  );
};

export default WorkExperience;
